<template><FormSection id="maintenance" :title="t('settings.cache_management')"><dl><template v-for="(v,k) in breakdown" :key="k"><dt>{{k}}</dt><dd>{{k==='totalCount'?v:format(v||0)}}</dd></template></dl><template #actions><ConfirmAction title="Clean archives" :confirm-label="t('cache.clean_archives')" :cancel-label="t('btn.cancel')" @confirm="$emit('clean','archives')"><template #trigger><button type="button">{{t('cache.clean_archives')}}</button></template></ConfirmAction><ConfirmAction title="Clean all cache" :description="t('cache.clean_warning')" :confirm-label="t('cache.clean_all')" :cancel-label="t('btn.cancel')" @confirm="$emit('clean','all')"><template #trigger><button data-action="cache-clean-all" type="button">{{t('cache.clean_all')}}</button></template></ConfirmAction></template></FormSection></template>
<script setup>import FormSection from '../FormSection.vue';import ConfirmAction from '../ConfirmAction.vue';defineProps({breakdown:{type:Object,default:()=>({})},t:{type:Function,required:true}});defineEmits(['clean']);const format=n=>n<1024?`${n} B`:`${(n/1024).toFixed(1)} KB`;</script><style scoped>dl{display:grid;grid-template-columns:repeat(2,minmax(100px,1fr));gap:8px}dt,dd{margin:0}</style>
